CREATE TABLE source_artifacts(source_id TEXT PRIMARY KEY REFERENCES sources(id),original_container TEXT NOT NULL,original_path TEXT NOT NULL,original_sha256 TEXT NOT NULL,original_bytes INTEGER NOT NULL,extraction_status TEXT NOT NULL);
CREATE TABLE national_reports(id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES sources(id),digest TEXT NOT NULL UNIQUE,title TEXT NOT NULL,mode TEXT NOT NULL CHECK(mode IN ('record','simulate')),effective_date TEXT,status TEXT NOT NULL DEFAULT 'review',revision INTEGER NOT NULL DEFAULT 1,correction_of TEXT REFERENCES national_reports(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TRIGGER report_original_immutable BEFORE UPDATE OF source_id,digest,mode,effective_date,correction_of ON national_reports BEGIN SELECT RAISE(ABORT,'Report originals are immutable; submit a corrective report'); END;
CREATE TRIGGER report_no_delete BEFORE DELETE ON national_reports BEGIN SELECT RAISE(ABORT,'Reports are preserved'); END;
CREATE TABLE report_actions(id TEXT PRIMARY KEY,report_id TEXT NOT NULL REFERENCES national_reports(id),ordinal INTEGER NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('movement_order','movement_arrival','record_event')),payload_json TEXT NOT NULL,line_start INTEGER NOT NULL,line_end INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','applied','rejected')),target_id TEXT,UNIQUE(report_id,ordinal));
CREATE TABLE report_reviews(id TEXT PRIMARY KEY,report_id TEXT NOT NULL REFERENCES national_reports(id),action TEXT NOT NULL,reason TEXT NOT NULL,before_json TEXT NOT NULL,after_json TEXT NOT NULL,recorded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TRIGGER report_reviews_no_update BEFORE UPDATE ON report_reviews BEGIN SELECT RAISE(ABORT,'Report reviews are append-only'); END;
CREATE TRIGGER report_reviews_no_delete BEFORE DELETE ON report_reviews BEGIN SELECT RAISE(ABORT,'Report reviews are append-only'); END;
